// seed-gfg-rich.mjs
// ------------------------------------------------------------
// This script loads the markdown files generated by generate-gfg-content.mjs
// and seeds them as lessons & topics into the existing "Data Analytics Tutorial"
// course. It adds deep explanations, coding exercises, quizzes, notes, etc.
// ------------------------------------------------------------

import fs from 'fs';
import path from 'path';
import mongoose from 'mongoose';
import { marked } from 'marked'; // convert markdown -> HTML

// ------------------------------------------------------------------
// Configuration – ensure a MongoDB connection string is provided.
// ------------------------------------------------------------------
const MONGODB_URI = process.env.MONGODB_URI;
if (!MONGODB_URI) {
  console.error('❌ MONGODB_URI environment variable is missing.');
  process.exit(1);
}

// Root folder where generate-gfg-content.mjs dumped markdown files.
const CONTENT_ROOT = path.resolve('generated-content');

// Utility – slugify for URLs.
function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '')
    .substring(0, 50);
}

async function main() {
  // ------------------------------------------------------------
  // 1️⃣ Connect to MongoDB
  // ------------------------------------------------------------
  await mongoose.connect(MONGODB_URI);
  const db = mongoose.connection.db;
  const courses = db.collection('courses');
  const lessons = db.collection('lessons');
  const topics = db.collection('topics');

  // ------------------------------------------------------------
  // 2️⃣ Find the target course – the existing Data Analytics tutorial.
  // ------------------------------------------------------------
  const target = await courses.findOne({ slug: 'data-analytics-tutorial' });
  if (!target) {
    console.error('❌ Target course "data-analytics-tutorial" not found.');
    process.exit(1);
  }
  console.log('✅ Seeding into course:', target.title?.en || target.title || target.slug);

  // ------------------------------------------------------------
  // 3️⃣ Load lesson folders (sorted alphabetically to keep order).
  // ------------------------------------------------------------
  const lessonFolders = fs.readdirSync(CONTENT_ROOT).filter(name => {
    const full = path.join(CONTENT_ROOT, name);
    return fs.statSync(full).isDirectory();
  }).sort();

  // Preserve any existing lessons – we will append after them.
  const existingLessonCount = await lessons.countDocuments({ course: target._id });
  let lessonOrder = existingLessonCount;
  const allLessonIds = [];

  for (const folder of lessonFolders) {
    const lessonTitle = folder.replace(/^\d{2}-/, '').replace(/-/g, ' ');
    const lessonRes = await lessons.insertOne({
      title: { en: lessonTitle },
      slug: slugify(lessonTitle) + '-' + Date.now().toString().slice(-4),
      course: target._id,
      order: lessonOrder++,
      description: { en: `Lesson covering ${lessonTitle}` },
      isPublished: true,
      createdAt: new Date(),
      updatedAt: new Date()
    });
    const lessonId = lessonRes.insertedId;
    allLessonIds.push(lessonId);

    // ------------------------------------------------------
    // 4️⃣ For each markdown file inside the lesson folder, create a topic.
    // ------------------------------------------------------
    const topicFiles = fs.readdirSync(path.join(CONTENT_ROOT, folder))
      .filter(f => f.endsWith('.md'))
      .sort();
    let topicOrder = 0;
    for (const file of topicFiles) {
      const rawMd = fs.readFileSync(path.join(CONTENT_ROOT, folder, file), 'utf8');
      const html = marked.parse(rawMd);
      const titleLine = rawMd.split('\n')[0].replace(/^#\s+/, '').trim();
      // Create a placeholder quiz for this topic
      const quizDoc = await db.collection('quizzes').insertOne({
        title: `${titleLine} Quiz`,
        questions: [
          {
            question: `What is the main concept behind ${titleLine}?`,
            options: ['Option A', 'Option B', 'Option C', 'Option D'],
            answer: 'Option A'
          }
        ],
        isPublished: true,
        createdAt: new Date(),
        updatedAt: new Date()
      });

      // Insert the topic with rich content fields
      await topics.insertOne({
        title: { en: titleLine },
        slug: slugify(titleLine) + '-' + Date.now().toString().slice(-4),
        course: target._id,
        lesson: lessonId,
        order: topicOrder++,
        content: rawMd,
        contentHtml: html,
        description: { en: `Topic ${titleLine}` },
        isPublished: true,
        // Rich interactive fields
        notes: [
          `Key take‑aways for ${titleLine}`,
          `Common pitfalls when applying ${titleLine}`
        ],
        datasets: [
          {
            name: `${titleLine} Sample Dataset`,
            url: 'https://example.com/dataset.csv',
            description: `A small CSV to practice ${titleLine}`
          }
        ],
        playgroundId: crypto.randomUUID(),
        milestones: [
          {
            title: `${titleLine} milestone`,
            description: `Complete the exercise for ${titleLine}`,
            completed: false
          }
        ],
        quizId: quizDoc.insertedId,
        quizzes: [quizDoc.insertedId],
        createdAt: new Date(),
        updatedAt: new Date()
      });
    }
  }

  // ------------------------------------------------------------
  // 5️⃣ Update the course document with the full lesson list.
  // ------------------------------------------------------------
  await courses.updateOne({ _id: target._id }, { $set: {
    lessons: allLessonIds,
    totalLessons: allLessonIds.length,
    updatedAt: new Date()
  }});

  console.log('✅ Seeding complete – all lessons & topics added with rich content.');
  process.exit(0);
}

main().catch(err => { console.error('Error:', err); process.exit(1); });
